module Supp_9_9cd # (parameter dp_width = 5) (  output 	[2*dp_width - 1: 0] 	Product,  output							Ready,  input 	[dp_width - 1: 0] 		Multiplicand, Multiplier,  input 							Start, clock, reset_b);  wire Load_regs, Incr_P, Add_regs, Shift_regs, Done, Q0;  Controller M0 (    Ready, Load_regs, Incr_P, Add_regs, Shift_regs, Start, Done, Q0,     clock, reset_b);Datapath M1(Product, Q0, Done, Multiplicand, Multiplier,  Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, reset_b);	endmodule/* // This alternative controller directly  produces the signals needed to control the datapath.module Controller (  output Ready,  output reg Load_regs, Incr_P, Add_regs, Shift_regs,     input Start, Done, Q0, clock, reset_b);  parameter	S_idle =		3'b001, 		// one-hot code        			S_add = 	3'b010, 		       			S_shift = 	3'b100;  reg	[2: 0]		state, next_state;		// sized for one-hot  assign		Ready = (state == S_idle);	    always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Done) begin    next_state = S_idle;    Load_regs = 0;    Incr_P = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:		if (Start) begin next_state = S_add; Load_regs = 1; end      S_add:	begin next_state = S_shift; Incr_P = 1; if (Q0) Add_regs = 1; end      S_shift:	begin Shift_regs = 1; 		  		  if (Done) next_state = S_idle; 		  		  else next_state = S_add;    end      default:	next_state = S_idle;    endcase  endendmodule*/// This controller has an embedded unit to generate T0, T1, and T2 and additional logic to form // // the signals needed to control the datapath.module Controller (  output Ready, Load_regs, Incr_P, Add_regs, Shift_regs,     input Start, Done, Q0, clock, reset_b);  State_Generator M0 (T0, T1, T2, Start, Done, Q0, clock, reset_b);  assign Ready = T0;  assign Load_regs = T0 && Start;  assign Incr_P = T1;  assign Add_regs = T1 && Q0;  assign Shift_regs = T2;endmodulemodule State_Generator (output T0,T1, T2, input Start, Done, Q0, clock, reset_b);  parameter		S_idle =	3'b001, 		// one-hot code        				S_add = 	3'b010, 		       				S_shift = 	3'b100;  reg	[2: 0]		state, next_state;		// sized for one-hot  assign 	T0 = (state == S_idle);  assign	T1 = (state == S_add);  assign	T2 = (state == S_shift);  always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  
  always @ (state, Start, Q0, Done) begin    next_state = S_idle;    case (state)      S_idle:		if (Start) next_state = S_add;       S_add:	next_state = S_shift;       S_shift:	if (Done) next_state = S_idle; else next_state = S_add;       default:	next_state = S_idle;    endcase  endendmodulemodule Datapath #(parameter dp_width = 5, BC_size = 3) (  output [2*dp_width - 1: 0] Product, output Q0, output Done,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Incr_P, Add_regs, Shift_regs, clock, reset_b);// Default configuration: 5-bit datapath  reg	[dp_width - 1: 0]		A, B, Q;				// Sized for datapath  reg 							C;  reg	[BC_size - 1: 0]		P;				// Bit counter    assign Q0 = Q[0];	  assign	Done = (P == dp_width ); 				// Multiplier is exhausted  assign Product = {C, A, Q};  always @ (posedge clock, negedge reset_b)     if (reset_b == 0) begin			// Added to this solution, but      P <= 0;  							// not really necessary since Load_regs      B <= 0;							// initializes the datapath      C <= 0;      A <= 0;      Q <= 0;    end     else begin    if (Load_regs) begin      P <= 0;       A <= 0;      C <= 0;      B <= Multiplicand;      Q <= Multiplier;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Incr_P) P <= P+1 ;   endendmodule module t_Supp_9_9cd;  parameter					dp_width = 5;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire							Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;  integer						Exp_Value;  reg							Error;  Supp_9_9cd M0(Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #115000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end 
 initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  always @ (negedge Start) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (posedge Ready) begin    # 1 Error <= (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;        repeat (32) #10 begin        Start = 1;        #10 Start = 0;        repeat (32) begin          Start = 1;          #10 Start = 0;                    #100 Multiplicand = Multiplicand + 1;        end      Multiplier = Multiplier + 1;    end  endendmodule